const heroArt=()=>`<svg class="hero-art" viewBox="0 0 245 180" fill="none" aria-hidden="true"><path d="M18 153C11 111 64 151 57 98S102 65 104 111s63 34 61-15 58-50 54-14" stroke="#769879" stroke-width="2" stroke-dasharray="5 6"/><circle cx="19" cy="153" r="5" fill="#d8ef9c"/><circle cx="217" cy="76" r="29" fill="#d8ef9c"/><text x="217" y="84" text-anchor="middle" fill="#214b3b" font-family="Arial,sans-serif" font-size="24" font-weight="700">7K</text><path d="m107 51 28 15 9 29 22 9-7 14-33-19-12-20-8 33-33 23-10-12 25-25 7-40" fill="#d8ef9c"/><circle cx="125" cy="29" r="12" fill="#f4ddc9"/><path d="m98 56-14 21-22 3m50-22 26 10 13-10" stroke="#f4ddc9" stroke-width="10" stroke-linecap="round"/><path d="m68 126-9 5-15-2m112-17 6 8 15 2" stroke="#fff9ed" stroke-width="8" stroke-linecap="round"/><path d="m41 34 2 8 8 2-8 2-2 8-2-8-8-2 8-2Z" fill="#a9c282"/></svg>`;
function showToday(){
 const d=day(),s=session(selected),t=targets(state,selected),g=goals(state,selected),score=dayScore(state,selected),future=selected>localDate(),disable=future?'disabled':'',weekday=dateObj(selected).getDay(),monday=addDays(selected,-((weekday+6)%7)),current=selected===localDate();
 let heading=current?`Let's make today count${state.settings.name?', '+esc(state.settings.name):''}.`:fmt(selected,{weekday:'long',month:'short',day:'numeric'});
 const weeks=Array.from({length:7},(_,i)=>{const date=addDays(monday,i);return `<button class="day-button ${date===selected?'active':''} ${date===localDate()?'is-today':''}" data-action="date" data-date="${date}" aria-label="${fmt(date,{weekday:'long',month:'long',day:'numeric'})}" aria-pressed="${date===selected}"><span class="weekday">${fmt(date,{weekday:'short'})}</span><b>${dateObj(date).getDate()}</b><span class="day-dot ${state.days[date]?'logged':''}"></span></button>`}).join('');
 const goalRows=g.filter(x=>x.id!=='water').map(x=>{
  const descriptions={workout:s.type==='recovery'?'Rest is part of getting stronger.':`${typeLabel(s)} · ${s.minutes?Math.round(s.minutes)+' min':'easy effort'}`,protein:'Build meals around a protein source.',sleep:d.sleep?`${d.sleep} hours logged · aim for 7–9`:'Log last night’s sleep.',steps:`${number(d.steps)} / ${number(t.steps)} · running steps count`};
  const isInput=['steps','sleep'].includes(x.id);return `<div class="goal-row ${x.done?'complete':''}"><button class="check ${x.done?'checked':''}" data-action="${isInput?'log':'toggle'}" data-key="${x.id}" aria-label="${isInput?'Log':x.done?'Uncheck':'Complete'} ${esc(x.label)}" ${!isInput?`aria-pressed="${x.done}"`:''} ${disable}>${x.done?icon('check'):''}</button><div class="goal-text"><strong>${esc(x.label)}</strong><small>${esc(descriptions[x.id]||'Your personal daily goal')}</small></div>${isInput?`<button class="goal-value" data-action="log" data-key="${x.id}" aria-label="Edit ${x.id}" ${disable}>${x.id==='steps'?(d.steps?number(d.steps):'+ Log'):(d.sleep?d.sleep+'h':'+ Log')}</button>`:x.custom?`<button class="text-button" data-action="remove-goal" data-key="${x.id}" aria-label="Remove ${esc(x.label)}" ${disable}>${icon('close')}</button>`:''}</div>`;
 }).join('');
 const runCount=runningSummary(activityHistory(state)).runs;
 return header(heading,current?fmt(selected,{weekday:'long',day:'numeric',month:'long'}):'Every day is a fresh start.')+
 `<section class="hero"><div><p class="eyebrow">YOUR ROAD TO 7K</p><h2>A little stronger.<br><em>Every day.</em></h2><p>Move your body. Fill your bottle.<br>Build a rhythm that feels like you.</p></div>${heroArt()}<span class="hero-tag">ONE STEP AT A TIME ↗</span></section>`+
 (localDate()<START?`<div class="prestart">${icon('spark')}<span>Your training begins November 1. Use today to find your rhythm.</span><button data-action="date" data-date="${START}">Preview day one ↗</button></div>`:'')+
 `<div class="section-heading"><h2>${current?'Your week':'Your day'}${!current?` <button class="text-button" data-action="date" data-date="${localDate()}">Back to today</button>`:''}</h2><div class="date-control"><button class="date-arrow" data-action="date" data-date="${addDays(selected,-7)}" aria-label="Previous week">${icon('left')}</button><input type="date" id="date-picker" aria-label="Choose a date" value="${selected}" min="2026-10-01" max="2027-12-31"><button class="date-arrow" data-action="date" data-date="${addDays(selected,7)}" aria-label="Next week">${icon('chevron')}</button></div></div><div class="week-strip">${weeks}</div>`+
 (future?'<p class="preview-label">Plan preview · logging opens on this date. You can view the workout now.</p>':'')+
 `${nativeApp?'<section class="card" style="margin-bottom:20px"><div class="card-title">Live tracking</div><p class="help">Outdoor sessions, daily phone steps and distance alerts.</p><button class="btn" data-action="live-tracking">Open live tracking</button></section>':''}${activityDayCard(selected,d)}<div class="grid-main"><div class="stack"><section class="card workout-card"><div class="card-title"><span class="title-icon">${icon(typeIcon(s))}Today’s movement</span><span class="tag">${s.week>0&&s.week<=13?'Week '+s.week:'Your pace'}</span></div><h3>${s.title}</h3><p class="workout-desc">${s.detail}</p><div class="workout-meta"><span>${icon('clock')}${s.minutes?Math.round(s.minutes)+' min':'Take it easy'}</span><span>${icon('leaf')}${s.type==='strength'?'No equipment':'Comfortable effort'}</span></div><div class="workout-actions"><button class="btn" data-action="${s.type==='strength'?'open-workout':'session'}" data-date="${selected}">${d.workout?icon('check'):icon('arrow')}${s.type==='strength'?'Guided workout':d.workout?'View completed session':'View session'}</button><button class="btn secondary" data-action="toggle" data-key="workout" ${disable}>${icon(d.workout?'undo':'check')}${d.workout?'Undo':'Mark done'}</button></div></section>
 <section class="card goals-card"><div class="goals-top"><div class="card-title">Your daily wins</div><span class="mini-score"><strong>${score.done}</strong> / ${score.total} complete</span></div>${goalRows}<button class="add-goal" data-action="add-goal" ${disable}>${icon('plus')}Add a personal goal</button></section>
 <section class="card mood-card"><div class="card-title">A quick check-in<span class="tag">Just for you</span></div><div class="moods">${[['great','☀','Good'],['okay','◡','Okay'],['tired','☾','Tired']].map(([id,symbol,label])=>`<button class="mood ${d.mood===id?'active':''}" data-action="mood" data-key="${id}" aria-pressed="${d.mood===id}" ${disable}><span aria-hidden="true">${symbol}</span>${label}</button>`).join('')}</div><textarea id="daily-note" placeholder="How did today feel? A small win, a little note…" maxlength="1000" aria-label="Daily journal note" ${disable}>${esc(d.note)}</textarea><p class="note-status">${storageOK&&!corrupt?'Notes save as you type, on this device.':'Device saving unavailable. Export a backup.'}</p></section></div>
 <div class="stack"><section class="card water-card"><div class="card-title"><span class="title-icon">${icon('drop')}A little hydration</span><span class="tag">${Math.round(d.water/t.water*100)}%</span></div><div class="water-visual"><div class="bottle" aria-hidden="true"><div class="bottle-inner"><div class="water-fill" style="height:${Math.min(100,d.water/t.water*100)}%"></div></div><div class="bottle-lines"><i></i><i></i><i></i><i></i></div></div><div class="water-stat"><div class="number">${number(d.water)}<span>ml</span></div><p>of your ${number(t.water)} ml daily goal</p><p class="water-message">${d.water>=t.water?'Goal reached. Let thirst guide you now.':d.water?'Little sips, steady progress.':'Your first sip is a small win.'}</p></div></div><div class="water-actions"><button class="btn" data-action="water" data-amount="250" ${disable}>${icon('plus')}250 ml</button><button class="btn" data-action="water" data-amount="500" ${disable}>${icon('plus')}500 ml</button><button class="btn undo" data-action="undo-water" aria-label="Undo last drink" ${disable||(!d.waterEntries.length?'disabled':'')}>${icon('undo')}</button></div><p class="water-note">Other drinks count too. Adjust to thirst, heat & activity.</p></section>
 <div class="summary-grid"><div class="mini-card"><div class="label">${icon('run')}Runs completed</div><div class="number">${runCount}<span>sessions</span></div><p>Your effort is adding up.</p></div><div class="mini-card"><div class="label">${icon('flag')}The next chapter</div><div class="number">7<span>km</span></div><p>February 1, 2027</p></div></div><div class="quote-card">${icon('leaf')}<p><strong>Progress has a gentle pace.</strong>Repeat a week when you need to. Recovery counts. Showing up matters.</p></div></div></div>`;
}
function showPlan(){
 const phases=['Find your rhythm','One small step more','Build your base','Settle into the habit','A little more running','Grow your endurance','Find your easy pace','An easier week','Longer, with confidence','Keep it comfortable','Trust your progress','Your longest practice','Rest up. You’re nearly there.'];
 const wk=weekOf(localDate());
 return header('Your road to 7K.','Thirteen weeks. Small steps. Plenty of room to grow.','THE BIG PICTURE')+`<section class="plan-intro"><div><p class="eyebrow">NOV 1 → FEB 1</p><h2>Build a rhythm. Go a little further.</h2><p>Three runs, two strength sessions, and space to recover. This is a guide, not a deadline. Repeat an easier session whenever you need to.</p></div><div class="big-seven">7<span>km</span></div></section><div class="plan-rules"><span class="pill">${icon('run')}3 easy runs / week</span><span class="pill">${icon('strength')}2 strength days</span><span class="pill">${icon('moon')}Recovery counts</span></div>`+
 Array.from({length:13},(_,i)=>{const week=i+1,start=addDays(TRAINING,i*7);return `<details class="week-card ${wk===week?'week-current':''}" ${week===Math.max(1,Math.min(wk,13))?'open':''}><summary><span class="week-number">${String(week).padStart(2,'0')}</span><div class="week-info"><h3>${phases[i]}</h3><p>${fmt(start)} – ${fmt(addDays(start,6))}</p></div>${[4,8,13].includes(week)?'<span class="tag">Ease back</span>':''}${icon('down')}</summary><div class="week-sessions">${Array.from({length:7},(_,n)=>{const date=addDays(start,n),s=session(date);return `<div class="plan-day"><span class="date-label">${fmt(date,{weekday:'short'})}<br>${fmt(date,{day:'numeric'})}</span><span class="session-icon">${icon(typeIcon(s))}</span><div class="session-details"><strong>${s.type==='run'?s.title:s.title}</strong><p>${s.detail}${s.type==='run'?' + 5 min walk before & after':''}</p></div><button data-action="session" data-date="${date}" aria-label="View session for ${fmt(date)}">View ↗</button></div>`}).join('')}</div></details>`}).join('')+
 `<section class="plan-end"><p class="eyebrow">MONDAY, FEBRUARY 1</p><h3>Your 7 km moment.</h3><p>Start easy and use walking breaks early. Attempt the distance only if your week-12 outing felt comfortable and you recovered normally. Otherwise, repeat an easier distance and give yourself more time.</p><button class="btn secondary small" data-action="date" data-date="${END}" style="margin-top:15px">Preview goal day ${icon('arrow')}</button></section>
 <details class="details-info"><summary>How to use this plan safely</summary><ul><li>Assumes you can walk briskly for 30 minutes without pain. If not, begin with comfortable walking and extend the timeline.</li><li>Run slowly enough to speak in full sentences. Walk 5 minutes before and after each run.</li><li>From week 9, try 4 minutes jogging / 1 minute walking on longer outings. Continuous running is optional.</li><li>Repeat a week if it feels too hard. Don’t catch up missed runs on consecutive days. After a missed week, restart with an easier completed session.</li><li>Stop for sharp or worsening pain. Chest pain, fainting, or unusually severe breathlessness needs urgent medical attention.</li><li>If you have a relevant medical condition or injury, get individual guidance before following the plan.</li></ul></details>
 <details class="details-info"><summary>Food, protein & recovery</summary><p>Build meals around a protein source, vegetables, and rice, roti or other carbohydrates. Use protein powder to fill a dietary gap; check the protein per serving. Avoid aggressive dieting while building your running base.</p><p>For healthy exercising adults, about 1.2–1.6 g protein/kg/day can be a starting range. This is not an individual prescription; kidney disease or prescribed restrictions need individual advice. Sleep 7–9 hours. Follow trends in weight and waist, not daily fluctuations.</p><p>Two litres is an editable hydration starting point, not a universal requirement. Other drinks count; adjust for heat, activity and thirst. Follow any prescribed fluid restriction.</p><div class="sources"><a href="https://www.nhs.uk/better-health/get-active/get-running-with-couch-to-5k/couch-to-5k-running-plan/" target="_blank" rel="noopener">NHS beginner running</a><a href="https://www.nhs.uk/live-well/eat-well/food-guidelines-and-food-labels/water-drinks-nutrition/" target="_blank" rel="noopener">NHS hydration</a><a href="https://ods.od.nih.gov/factsheets/ExerciseAndAthleticPerformance-HealthProfessional/" target="_blank" rel="noopener">NIH sports nutrition</a></div></details>`;
}
function showProgress(){
 const today=localDate(),entries=Object.entries(state.days).filter(([date])=>date<=today).sort(([a],[b])=>a.localeCompare(b)),activities=activityHistory(state),summary=runningSummary(activities),runs=summary.runs,strength=entries.filter(([date,d])=>d.workout&&session(date).type==='strength'),totalKm=summary.km,hydrated=entries.filter(([date,d])=>d.water>=targets(state,date).water).length;
 const seven=Array.from({length:7},(_,i)=>addDays(today,i-6));
 const chart=seven.map(date=>{const x=dayScore(state,date),percent=state.days[date]?x.done/x.total*100:0;return `<div class="chart-col ${date===today?'today':''}"><div class="bar-space" role="img" aria-label="${fmt(date)}: ${Math.round(percent)} percent of goals"><div class="bar" style="height:${percent}%"></div></div><span>${fmt(date,{weekday:'short'})}</span></div>`}).join('');
 const metrics=entries.filter(([,d])=>d.weight||d.waist),weights=metrics.filter(([,d])=>d.weight);
 let spark='';if(weights.length>1){const last=weights.slice(-12),min=Math.min(...last.map(([,d])=>d.weight))-1,max=Math.max(...last.map(([,d])=>d.weight))+1,points=last.map(([date,d],i)=>`${10+i*280/(last.length-1)},${75-(d.weight-min)/(max-min)*60}`).join(' ');spark=`<svg class="sparkline" viewBox="0 0 300 90" role="img" aria-label="Weight trend from ${last[0][1].weight} to ${last.at(-1)[1].weight} kilograms"><path d="M10 75h280" stroke="#e7e9e0"/><polyline points="${points}" fill="none" stroke="#7f9d59" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg>`}
 return header('Look how far you’ve come.','Small wins become a stronger routine.','YOUR PROGRESS')+`<div class="stat-cards">${[['run','Runs completed',runs,'Easy effort adds up.'],['strength','Strength sessions',strength.length,'A stronger foundation.'],['steps','Distance logged',Number(totalKm.toFixed(1))+' km','Run distance · synced or logged.'],['drop','Hydration days',hydrated,'Days you reached your goal.']].map(([i,label,val,caption])=>`<div class="mini-card"><div class="label">${icon(i)}${label}</div><div class="number">${val}</div><p>${caption}</p></div>`).join('')}</div><section class="card activity-list" style="margin-bottom:20px"><div class="card-title">Activity history <span class="tag">All sources</span></div>${activities.length?activities.slice(0,50).map(a=>`<div class="history-row"><span><strong>${a.type==='run'?'Run':'Walk'} · ${fmt(a.date)} </strong><small>${a.source}${a.possiblyDuplicate?' · manual entry, possibly already tracked':''}${a.minutes?` · ${Math.round(a.minutes)} min`:''}</small></span><strong>${a.km===null?'—':a.km.toFixed(2)+' km'}</strong></div>`).join(''):'<p class="help">No activities yet. Start a live session, sync Samsung Health, or log a run.</p>'}<p class="help">Samsung and live sessions with matching start time, duration and distance appear once. Manual runs on a day already tracked are shown but excluded from running totals to avoid double counting. Older live sessions without a start time can’t be matched with certainty.</p></section><div class="progress-layout"><div class="stack"><section class="card"><div class="card-title">Your last seven days<span class="tag">Daily goals</span></div><div class="chart-bars">${chart}</div><p class="chart-caption">Each bar is the share of daily goals completed. A quieter day is part of the journey.</p></section><section class="card"><div class="card-title">Your recent days</div>${entries.length?entries.slice(-10).reverse().map(([date,d])=>{const score=dayScore(state,date);return `<div class="history-row"><span><strong>${fmt(date,{weekday:'short',month:'short',day:'numeric'})}</strong><small>${number(d.water)} ml · ${number(d.steps)} steps${runDistance(d)?' · '+Number(runDistance(d).toFixed(2))+' km run':''}</small></span><small>${score.done}/${score.total} wins</small><button data-action="date" data-date="${date}">View</button></div>`}).join(''):`<div class="empty-state">${icon('leaf')}<h3>Your story starts with today.</h3><p>Log a drink or tick a daily goal.<br>Your progress will appear here.</p></div>`}</section></div><div class="stack"><section class="card"><div class="card-title"><span class="title-icon">${icon('scale')}Body check-in</span><button class="text-button" data-action="measure">${icon('plus')}Log</button></div>${weights.length?`<div class="number" style="font-size:34px;margin-top:22px">${weights.at(-1)[1].weight}<span style="font-size:13px;color:var(--muted)"> kg</span></div><p class="help">Latest · ${fmt(weights.at(-1)[0])}</p>${spark}`:''}${metrics.length?`<table class="metric-table"><thead><tr><th>Date</th><th>Weight</th><th>Waist</th></tr></thead><tbody>${metrics.slice(-6).reverse().map(([date,d])=>`<tr><td>${fmt(date)}</td><td>${d.weight?d.weight+' kg':'—'}</td><td>${d.waist?d.waist+' cm':'—'}</td></tr>`).join('')}</tbody></table>`:'<div class="empty-state"><h3>More than a number.</h3><p>Optional weight and waist check-ins.<br>Watch the trend, not one measurement.</p></div>'}<p class="help">Compare similar morning conditions. Check waist every two weeks; weight 2–3 times a week if useful.</p></section><div class="quote-card">${icon('heart')}<p><strong>Consistency over perfection.</strong>Energy, strength and easier runs are progress too.</p></div></div></div>`;
}
function showSettings(){const s=state.settings;const permission='Notification'in window?Notification.permission:'unsupported';return header('Make it work for you.','Your goals, your reminders, your rhythm.','THE LITTLE DETAILS')+
 `<div class="settings-grid"><div class="stack"><section class="card"><div class="card-title">Your daily goals ${icon('flag')}</div><form id="goals-form"><div class="form-grid"><label class="field wide">What should we call you?<input name="name" value="${esc(s.name)}" maxlength="40" autocomplete="given-name"></label><label class="field">Fluids · ml / day<input name="waterGoal" type="number" min="500" max="5000" step="50" value="${s.waterGoal}" required inputmode="numeric"></label><label class="field">Steps / day<input name="stepGoal" type="number" min="1000" max="30000" step="100" value="${s.stepGoal}" required inputmode="numeric"></label></div><button class="btn full" type="submit">Save my goals ${icon('check')}</button></form><p class="help">Running steps count toward your total. Recovery days have no step quota. Hydration needs vary; adjust for thirst, activity, heat and medical advice. Logged days keep their original targets.</p></section>
 ${healthSettingsCard()}<section class="card"><div class="card-title">Keep Stride close ${icon('home')}</div><p class="help">Open your Stride link on your phone. No ChatGPT account is needed. Add it to your home screen for quick access.</p><ul class="install-list"><li><strong>iPhone:</strong> open in Safari → Share → Add to Home Screen.</li><li><strong>Android:</strong> open in Chrome → menu → Add to Home screen / Install app.</li></ul>${installPrompt?'<button class="btn outline full" data-action="install" style="margin-top:13px">Add Stride to home screen</button>':''}<p class="help">Use the same browser or home-screen app each time. Some phones keep their storage separate. ${nativeApp?'This Android app also opens offline. Browser and Android app storage are separate; use backups to transfer your records.':'An internet connection is required to open the site.'}</p></section>
 <section class="card"><div class="card-title">Your data stays with you ${icon('heart')}</div><p class="help">Logs are saved on this device. There is no cloud account sync. Samsung Health syncing is available in the separate Android app. Clearing app or site data removes them. Export a backup regularly or before changing phones.</p><div class="button-row"><button class="btn outline" data-action="export">${icon('download')}Export backup</button><button class="btn outline" data-action="import">${icon('upload')}Restore backup</button></div>${corrupt?'<button class="text-button" data-action="reset-corrupt">Reset unreadable data</button>':''}<p class="help">Backup files include planner, imported and finished live sessions. Keep them somewhere private.</p></section></div>
 <div class="stack"><section class="card"><div class="card-title"><span class="title-icon">${icon('bell')}A nudge when you need it</span></div><form id="reminders-form"><label class="toggle-row"><span>Activity reminders<small>Run, strength and mobility days</small></span><input class="toggle" name="activityReminders" type="checkbox" ${s.activityReminders?'checked':''} aria-label="Activity reminders"></label><div class="form-grid"><label class="field">Run & mobility time<input type="time" name="runTime" value="${s.runTime}" required></label><label class="field">Strength time<input type="time" name="strengthTime" value="${s.strengthTime}" required></label></div><label class="toggle-row"><span>Water reminders<small>Gentle breaks, during your waking hours</small></span><input class="toggle" name="waterReminders" type="checkbox" ${s.waterReminders?'checked':''} aria-label="Water reminders"></label><div class="form-grid"><label class="field">First nudge<input type="time" name="waterStart" value="${s.waterStart}" required></label><label class="field">Last nudge<input type="time" name="waterEnd" value="${s.waterEnd}" required></label><label class="field wide">Nudge me every<select name="waterInterval">${[[60,'1 hour'],[90,'90 minutes'],[120,'2 hours'],[180,'3 hours'],[240,'4 hours']].map(([n,label])=>`<option value="${n}" ${s.waterInterval===n?'selected':''}>${label}</option>`).join('')}</select></label></div><div id="reminder-error" class="form-error" role="alert"></div><button class="btn full" type="submit">Save reminder times ${icon('check')}</button></form><div class="notice">Times use your phone’s local time. Save your times, then enable phone alerts below or import the calendar.</div></section>
 ${nativeApp?`<section class="card"><div class="card-title">Water reminders on this phone</div><p class="help">Get quiet-hour-aware water nudges even when Stride is closed. Reminders stop for the day once your logged water reaches your goal. Times may arrive late due to Android battery settings.</p><button class="btn full" data-action="water-phone">${window.AndroidStride.waterReminderEnabled()?'Turn off phone water reminders':'Enable phone water reminders'}</button><p class="help">Save times above first. Allow notifications when asked. Your browser calendar is a separate option; avoid enabling both if you prefer one reminder.</p></section>`:''}<section class="card"><div class="card-title">Phone calendar reminders<span class="tag">Works when closed</span></div><p class="help">Download your schedule and import it into Apple Calendar or Google Calendar. It includes activity times and water breaks from ${fmt(localDate()>START?localDate():START)} through February 1, with an alert at each event’s start.</p><button class="btn full" data-action="calendar" style="margin-top:17px">${icon('download')}Download reminder calendar</button><details class="details-info"><summary>How to turn on phone alerts</summary><ol class="install-list"><li>Save your reminder times above, then download the .ics calendar.</li><li><strong>Apple Calendar:</strong> open the file and use the calendar import option. If your iPhone offers only a preview, import it through Calendar on a Mac into an iCloud calendar synced to your phone.</li><li><strong>Google Calendar:</strong> open the website on a computer → Settings → Import & export → Import the .ics file. Choose a dedicated Stride calendar that syncs to your phone.</li><li>Enable notifications for your calendar app and calendar. Check the imported events and alerts; some calendars may ignore imported alarms.</li></ol><p>Changing settings here does not update an imported calendar. Remove the old Stride calendar/events before importing again to avoid duplicates. No alerts are enabled until you finish the import.</p></details></section>
 <section class="card"><div class="card-title">While Stride is open ${icon('bell')}</div><p class="help">Optional browser alerts at your saved times. This requires Stride to stay open and your browser to support notifications. It is not background push; phones may suspend the page.</p><div class="notice blue">${s.browserReminders&&permission==='granted'?'Open-page alerts are enabled on this browser.':permission==='denied'?'Notifications are blocked. Use calendar reminders or change this site’s notification permission in your browser.':permission==='unsupported'?'This browser does not support these alerts. Use calendar reminders.':'Browser alerts are currently off.'}</div><div class="button-row"><button class="btn outline" data-action="notifications">${s.browserReminders?'Turn off':'Enable open-page alerts'}</button><button class="btn outline" data-action="test-notification">Test alert</button></div></section></div></div>`;}

function activityDayCard(date,d){
 const h=d.health,items=activityHistory(state).filter(x=>x.date===date);
 if(!h&&!items.length)return '';
 const rows=items.map(x=>`<div class="history-row"><span><strong>${x.type==='run'?'Run':'Walk'}</strong><small>${esc(x.source)} · ${Math.round(x.minutes||0)} min${x.possiblyDuplicate?' · possible duplicate':''}</small></span><strong>${x.km===null?'Distance unavailable':Number(x.km.toFixed(2))+' km'}</strong></div>`).join('');
 return `<section class="card" style="margin:0 0 22px"><div class="card-title">${icon('steps')}Activity <span class="tag">All sources</span></div>${rows||'<p class="help">No running or walking sessions for this day.</p>'}${h?`<p class="help">${h.steps===null?'No Samsung step total was shared; your manual total was kept.':number(h.steps)+' Samsung steps shared.'} Phone-sensor steps stay separate and are never added to Samsung totals.</p>`:''}</section>`;
}
function healthSettingsCard(){return `${nativeApp?'<section class="card"><div class="card-title">Live tracking & goal alerts</div><p class="help">Track outdoor runs and walks, count daily steps, and get a notification when your target is reached. Your profile and history stay on this phone. Set your name and daily step target above first.</p><button class="btn full" data-action="live-tracking">Open live tracking</button></section>':''}<section class="card"><div class="card-title">${icon('steps')}Samsung Health<span class="tag">Free · Android 14+</span></div>${nativeApp?`<p class="help">Read your last seven days of Samsung Health steps, runs and walks through Health Connect. Preview before importing. Sync again whenever you want an update.</p><button class="btn full" data-action="health-sync" style="margin-top:16px">Sync Samsung Health ${icon('arrow')}</button><p class="notice">In Samsung Health → Settings → Health Connect, allow Samsung Health to share steps, exercise and distance. Open Samsung Health to finish syncing first. Stride requests read-only access; it never changes Samsung Health.</p>`:`<p class="help">Automatic access needs the Stride Android app. This website cannot directly read Samsung Health.</p><a class="btn full" href="./stride-android.apk" style="margin-top:16px" download>Download Android app ${icon('download')}</a><p class="help">Personal-use app for Android 14 or newer. Install it, then open Settings → Sync Samsung Health. No subscription, paid API or cloud database.</p>`}<p class="help">App and browser records are separate. Export a backup here and restore it in the Android app to move your existing logs. Export from the Android app to bring synced records back here. The Android app stores your records on your device and does not upload them.</p>${beforeHealthSync?'<button class="btn outline full" data-action="health-undo">Undo last sync</button>':''}<p class="help">Android features are compiled and checked, but need verification on your phone. Distance depends on what Samsung Health shares. Samsung Health routes are not requested. Live tracking uses GPS only when you start an activity.</p></section>`}
window.addEventListener('stride-health-result',event=>{
 try{
  pendingHealth=parseHealthSync(event.detail,localDate());
  if(corrupt){toast('Restore your saved data before syncing.');return}
  const sessions=pendingHealth.flatMap(d=>d.sessions);
  if(!sessions.length&&pendingHealth.every(d=>d.steps===null)){pendingHealth=null;toast('No Samsung Health data shared yet. Check Health Connect permissions, open Samsung Health, then try again.');return}
  modal('Your Samsung Health update','Check these days before importing.',`<p class="modal-text">This replaces step totals only where Samsung Health supplied data. Run and walk sessions are stored separately; your manual logs and other habits stay intact. Synced run distances take priority in Progress. Repeated syncing does not add duplicates.</p>${pendingHealth.map(d=>`<div class="history-row"><strong>${fmt(d.date)}</strong><span>${d.steps===null?'No steps shared':number(d.steps)+' steps'} · ${d.sessions.length} sessions</span></div>`).join('')}<div class="modal-footer"><button class="btn outline" data-action="close">Cancel</button><button class="btn" data-action="health-apply">Import ${pendingHealth.length} days ${icon('check')}</button></div>`);
 }catch{pendingHealth=null;toast('Could not read the Samsung Health update. No saved data was changed.');}
});
window.addEventListener('stride-native-message',event=>toast(String(event.detail||'')));


function workoutDate(){if(session(selected).type==='strength')return selected;for(let i=0;i<7;i++){const d=addDays(localDate()<TRAINING?TRAINING:localDate(),i);if(session(d).type==='strength')return d;}return selected;}
function showWorkout(){const date=workoutDate(),plan=session(date),future=date>localDate(),exercises=EXERCISES[plan.variant]||EXERCISES.A,d=state.days[date]||emptyDay(),counts=d.strength?.counts||exercises.map((_,i)=>d.exercises[i]?requiredSets(plan.week,i):0),i=Math.min(5,workoutStep),[name,reps,cue]=exercises[i],guide=GUIDE[name],limit=requiredSets(plan.week,i),done=counts.reduce((n,x,j)=>n+Math.min(x,requiredSets(plan.week,j)),0),total=exercises.reduce((n,_,j)=>n+requiredSets(plan.week,j),0);
 return header('Strength, one set at a time.','No equipment. A clear cue for every move.','YOUR GUIDED WORKOUT')+`<div class="workout-shell"><section class="card workout-focus"><div class="workout-progress"><span>Home strength ${plan.variant||'A'} · ${fmt(date)}</span><strong>${done} / ${total} sets</strong></div><div class="workout-track"><span style="width:${100*done/total}%"></span></div>${future?'<p class="notice">This planned session opens on its date. You can preview each exercise now.</p>':''}<div class="movement-number">MOVE ${String(i+1).padStart(2,'0')} / 06</div><h2>${esc(name)}</h2><p class="movement-dose">${limit} sets · ${esc(reps)} · ${counts[i]||0} done</p><div class="tutorial"><h3>How to do it</h3><ol>${guide.steps.map(step=>`<li>${esc(step)}</li>`).join('')}</ol><div class="technique"><strong>Form check</strong><span>${esc(guide.check)}</span></div><div class="technique"><strong>Make it easier</strong><span>${esc(guide.easier)}</span></div></div><p class="help">${esc(cue)} Stop if something hurts. Move at a pace you can control.</p><div class="workout-controls"><button class="btn outline" data-action="workout-prev" ${i===0?'disabled':''}>Previous</button><button class="btn" data-action="workout-set" ${future||counts[i]>=limit?'disabled':''}>${counts[i]>=limit?'Sets done':'Complete set'}</button><button class="btn outline" data-action="workout-next" ${i===5?'disabled':''}>Next</button></div><div class="rest-control"><span id="rest-countdown">${restUntil&&restUntil>Date.now()?Math.ceil((restUntil-Date.now())/1000)+'s rest remaining':'Rest 60 seconds between sets'}</span><button data-action="rest-skip">Skip rest</button></div></section><section class="card workout-list"><div class="card-title">Today’s moves</div>${exercises.map(([label],n)=>`<button class="workout-item ${n===i?'active':''}" data-action="workout-select" data-index="${n}"><span class="exercise-number">${n+1}</span><span><strong>${esc(label)}</strong><small>${counts[n]||0}/${requiredSets(plan.week,n)} sets</small></span>${counts[n]>=requiredSets(plan.week,n)?icon('check'):icon('chevron')}</button>`).join('')}<p class="help">Warm up 3–5 minutes. Leave a couple of comfortable reps in reserve. Your completed sets save automatically.</p>${d.workout?'<div class="notice">Session complete. You can revisit the tutorials anytime.</div>':''}</section></div>`;}

function render(){nav();$('#main').innerHTML=({today:showToday,plan:showPlan,workout:showWorkout,progress:showProgress,settings:showSettings}[view])();document.title=`${{today:'Today',plan:'My plan',workout:'Strength',progress:'Progress',settings:'Settings'}[view]} · Stride`;}
function go(next){view=next;location.hash=next;render();window.scrollTo({top:0,behavior:'instant'})}
function modal(title,subtitle,body){$('#modal').innerHTML=`<div class="modal-header"><div><h2 id="modal-title">${title}</h2><p>${subtitle}</p></div><button data-action="close" aria-label="Close dialog">${icon('close')}</button></div>${body}`;if(!$('#modal').open)$('#modal').showModal();}
function showSession(date){
 modalDate=date;const s=session(date),d=day(date),future=date>localDate(),disabled=future?'disabled':'';
 let body='';if(s.type==='run'){body=`<div class="session-block"><b>01 · Warm up</b>Walk comfortably for 5 minutes.</div><div class="session-block"><b>02 · ${s.goal?'Your 7 km goal':'Your easy effort'}</b>${s.detail}<br><span class="modal-text">${s.week>=9?'Try 4 minutes jogging / 1 minute walking, or run continuously if comfortable. ':'Keep a pace where you can speak in complete sentences. '}${s.goal?'Continue only if your longer practice and recovery went well.':''}</span></div><div class="session-block"><b>03 · Cool down</b>Walk for 5 minutes. Finish feeling you could do a little more.</div><form id="run-log-form" data-date="${date}"><div class="form-grid"><label class="field">Distance · km (optional)<input type="number" name="km" min="0" max="1000" step="0.01" inputmode="decimal" value="${d.km||''}" placeholder="e.g. 2.5" ${disabled}></label><label class="field">Total time · min (optional)<input type="number" name="minutes" min="0" max="1440" step="1" inputmode="numeric" value="${d.minutes||''}" placeholder="e.g. 30" ${disabled}></label></div><button class="btn full" type="submit" ${disabled}>${icon('check')}${d.workout?'Save session log':'Save & mark complete'}</button></form>`;}
 else if(s.type==='strength'){body=`<p class="modal-text">Warm up for 3–5 minutes. Rest 60–90 seconds between sets. Finish each set with 2–3 good reps left. Tick an exercise after completing its sets.</p>${EXERCISES[s.variant].map(([name,reps,cue],i)=>`<div class="exercise"><button class="check ${d.exercises[i]?'checked':''}" data-action="exercise" data-index="${i}" aria-label="${d.exercises[i]?'Uncheck':'Complete'} ${name}" aria-pressed="${!!d.exercises[i]}" ${disabled}>${d.exercises[i]?icon('check'):''}</button><div><strong>${name}</strong><p class="reps">${setsFor(s.week,i)} sets · ${reps}</p><small>${cue}</small></div></div>`).join('')}<p class="help">When the top rep range feels comfortable twice, progress to a slightly harder variation or slower lowering. Keep Friday leg work light.</p><div class="modal-footer"><button class="btn" data-action="complete-session" ${disabled}>${icon('check')}${d.workout?'Session completed':'Mark session complete'}</button></div>`;}
 else{const text=s.type==='mobility'?'Take a comfortable walk. Spend 10 minutes on gentle ankle circles, hip movements, shoulder circles and comfortable calf stretches. Avoid painful ranges.':s.type==='recovery'?'No workout or step quota today. Rest, sleep well, and take a gentle walk only if you feel like it. Recovery is part of the plan.':'Take a comfortable 20–30 minute walk if it feels good. Notice your current step average, fill your bottle and choose a regular workout time. No need to push.';body=`<p class="modal-text">${text}</p><div class="modal-footer"><button class="btn" data-action="complete-session" ${disabled}>${icon('check')}${d.workout?'Day checked in':'Mark complete'}</button></div>`;}
 if(future)body+='<p class="notice">This session is a preview. Logging opens on this date.</p>';
 modal(s.title,`${fmt(date,{weekday:'long',month:'short',day:'numeric'})} · ${typeLabel(s)}`,body);
}
function showLog(key){if(!canEdit())return;const d=day(),configs={steps:['Daily steps','Every step counts, including your run.',100000,1,'steps'],sleep:['Last night’s sleep','A gentle goal: 7–9 hours.',24,.25,'hours']},[title,sub,max,step,unit]=configs[key];modal(title,sub,`<form id="log-form" data-key="${key}"><label class="field">Total ${unit}<input class="big-input" name="value" type="number" min="0" max="${max}" step="${step}" inputmode="${key==='sleep'?'decimal':'numeric'}" value="${d[key]||''}" placeholder="0" required autofocus></label><div class="modal-footer"><button class="btn" type="submit">Save ${icon('check')}</button></div></form>`);}
function showMeasure(){const date=selected>localDate()?localDate():selected,d=day(date);modal('A body check-in','Optional. Your strength and energy matter too.',`<form id="measure-form"><div class="form-grid"><label class="field wide">Date<input type="date" name="date" value="${date}" min="2026-10-01" max="${localDate()}" required></label><label class="field">Weight · kg<input type="number" name="weight" min="20" max="400" step=".1" inputmode="decimal" value="${d.weight??''}"></label><label class="field">Waist · cm<input type="number" name="waist" min="30" max="250" step=".1" inputmode="decimal" value="${d.waist??''}"></label></div><p class="help">Blank fields clear that measurement for the selected date.</p><button class="btn full" type="submit">Save check-in ${icon('check')}</button></form>`);}
function download(name,content,type){if(nativeApp){window.AndroidStride.saveFile(name,content,type.split(';')[0]);return;}const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000)}
async function notify(message){if(!('Notification'in window)||Notification.permission!=='granted')return false;try{new Notification('Stride · a little nudge',{body:message,icon:'./icon-192.png',tag:'stride-reminder'});return true}catch{return false}}
document.addEventListener('click',async event=>{
 const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action,k=el.dataset.key;
 if(a==='live-tracking'){if(nativeApp)window.AndroidStride.openLiveTracking(state.settings.name,state.settings.stepGoal);return}
 if(a==='health-sync'){if(nativeApp)window.AndroidStride.syncSamsungHealth();return}
 if(a==='health-apply'){
  if(!pendingHealth||corrupt){toast('Restore your saved data before syncing.');return}
  beforeHealthSync=pendingHealth.map(h=>({date:h.date,health:day(h.date).health?JSON.parse(JSON.stringify(day(h.date).health)):null,steps:day(h.date).steps,syncedSteps:h.steps}));
  for(const h of pendingHealth){const d=editDay(h.date);d.health={steps:h.steps,sessions:h.sessions,syncedAt:h.syncedAt};if(h.steps!==null)d.steps=h.steps;}
  pendingHealth=null;$('#modal').close();saved('Samsung Health synced. Other daily habits were kept.');return;
 }
 if(a==='health-undo'){if(!beforeHealthSync)return;for(const old of beforeHealthSync){const d=editDay(old.date);if(old.health)d.health=old.health;else delete d.health;if(old.syncedSteps!==null&&d.steps===old.syncedSteps)d.steps=old.steps;}beforeHealthSync=null;saved('Last sync undone. Later edits to other habits were kept.');return}
 if(a==='view'){go(el.dataset.view);return}
 if(a==='date'){selected=el.dataset.date;go('today');return}
 if(a==='close'){$('#modal').close();return}
 if(a==='session'){showSession(el.dataset.date);return}
 if(a==='log'){showLog(k);return}
 if(a==='toggle'){if(!canEdit())return;const d=editDay();if(k==='workout'||k==='protein')d[k]=!d[k];else{const c=d.custom.find(c=>c.id===k);if(c)c.done=!c.done}saved();return}
 if(a==='water'){if(!canEdit())return;const d=editDay(),amt=Number(el.dataset.amount);if(d.water+amt>20000){toast('Check today’s fluid log before adding more.');return}d.water+=amt;d.waterEntries.push(amt);saved(d.water>=targets(state,selected).water?'Hydration goal reached. Let thirst guide you.':`${amt} ml logged. A small win.`);return}
 if(a==='undo-water'){if(!canEdit())return;const d=editDay(),last=d.waterEntries.pop();if(last)d.water=Math.max(0,d.water-last);saved('Last drink removed.');return}
 if(a==='mood'){if(!canEdit())return;const d=editDay();d.mood=d.mood===k?'':k;saved();return}
 if(a==='add-goal'){if(!canEdit())return;if(day().custom.length>=12){toast('You have 12 personal goals. Keep today manageable.');return}modal('One small intention.','Add a personal goal for this day.',`<form id="custom-form"><label class="field">My goal<input name="label" maxlength="80" placeholder="e.g. Take a screen-free lunch break" required autofocus></label><div class="modal-footer"><button class="btn" type="submit">Add to my day ${icon('plus')}</button></div></form>`);return}
 if(a==='remove-goal'){if(!canEdit())return;editDay().custom=day().custom.filter(c=>c.id!==k);saved('Personal goal removed.');return}
 if(a==='exercise'){if(!canEdit(modalDate))return;const d=editDay(modalDate),i=el.dataset.index;d.exercises[i]=!d.exercises[i];save();render();el.classList.toggle('checked',d.exercises[i]);el.setAttribute('aria-pressed',String(d.exercises[i]));el.innerHTML=d.exercises[i]?icon('check'):'';return}
 if(a==='complete-session'){if(!canEdit(modalDate))return;editDay(modalDate).workout=true;$('#modal').close();saved('Movement checked in. Nicely done.');return}
 if(a==='measure'){showMeasure();return}
 if(a==='export'){let content=JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2);if(corrupt){try{content=localStorage.getItem(KEY)||content}catch{}}download(`stride-backup-${localDate()}.json`,content,'application/json');toast(nativeApp?'Choose where to save your private backup.':'Backup download started. Keep it somewhere private.');return}
 if(a==='import'){$('#import-file').click();return}
 if(a==='reset-corrupt'){if(confirm('Reset the unreadable local data? Export it first if you want to keep a copy.')){corrupt=false;saved('A fresh start is ready.')}return}
 if(a==='calendar'){const c=calendar(state,localDate(),nativeApp?'https://seven-marathon.netlify.app/':location.origin);if(!c.count){toast('No upcoming reminders. Check your reminder settings and dates.');return}download('stride-reminders.ics',c.text,'text/calendar;charset=utf-8');toast(nativeApp?'Save the calendar, then import it to enable alerts.':'Calendar downloaded. Import it to enable phone alerts.');return}
 if(a==='notifications'){if(state.settings.browserReminders){state.settings.browserReminders=false;saved('Open-page alerts turned off.');return}if(!('Notification'in window)){toast('Use calendar reminders on this browser.');return}try{const p=await Notification.requestPermission();if(p==='granted'){state.settings.browserReminders=true;saved('Open-page alerts enabled. Keep Stride open.')}else{render();toast('Permission wasn’t granted. Calendar reminders are available.')}}catch{toast('Browser alerts unavailable. Use calendar reminders.')}return}
 if(a==='test-notification'){const ok=await notify('You’re all set. This is a test reminder.');toast(ok?'Test alert sent.':'No alert sent. Enable supported browser alerts or use your calendar.');return}
 if(a==='install'&&installPrompt){await installPrompt.prompt();installPrompt=null;render();}
});
document.addEventListener('submit',event=>{
 const form=event.target;if(!['goals-form','reminders-form','log-form','custom-form','run-log-form','measure-form'].includes(form.id))return;event.preventDefault();if(!form.reportValidity())return;const fd=new FormData(form),val=k=>fd.get(k);
 if(form.id==='goals-form'){state.settings.name=String(val('name')).trim().slice(0,40);state.settings.waterGoal=Number(val('waterGoal'));state.settings.stepGoal=Number(val('stepGoal'));saved('Goals saved for new days. Existing logs keep their targets.');if(nativeApp&&window.AndroidStride.waterReminderEnabled())window.AndroidStride.configureWater(true,state.settings.waterStart,state.settings.waterEnd,state.settings.waterInterval,state.settings.waterGoal);return}
 if(form.id==='reminders-form'){if(val('waterStart')>val('waterEnd')){$('#reminder-error').textContent='Set the last water reminder after the first one.';return}for(const k of ['runTime','strengthTime','waterStart','waterEnd'])state.settings[k]=val(k);state.settings.waterInterval=Number(val('waterInterval'));for(const k of ['activityReminders','waterReminders'])state.settings[k]=fd.has(k);saved(nativeApp?'Reminder times saved. Enable phone alerts below if needed.':'Times saved. Import a calendar to enable phone alerts.');if(nativeApp&&window.AndroidStride.waterReminderEnabled())window.AndroidStride.configureWater(state.settings.waterReminders,state.settings.waterStart,state.settings.waterEnd,state.settings.waterInterval,state.settings.waterGoal);return}
 if(form.id==='log-form'){if(!canEdit())return;editDay()[form.dataset.key]=Number(val('value'));$('#modal').close();saved('Saved to your day.');return}
 if(form.id==='custom-form'){if(!canEdit())return;const label=String(val('label')).trim();if(!label)return;editDay().custom.push({id:'custom-'+Date.now(),label,done:false});$('#modal').close();saved('A new intention for today.');return}
 if(form.id==='run-log-form'){const date=form.dataset.date;if(!canEdit(date))return;const d=editDay(date);d.km=Number(val('km')||0);d.minutes=Number(val('minutes')||0);d.workout=true;$('#modal').close();saved('Run saved. One step stronger.');return}
 if(form.id==='measure-form'){const date=val('date');if(!canEdit(date))return;const d=editDay(date);d.weight=val('weight')?Number(val('weight')):null;d.waist=val('waist')?Number(val('waist')):null;$('#modal').close();saved('Check-in saved.');}
});
document.addEventListener('input',event=>{if(event.target.id==='daily-note'&&selected<=localDate()){editDay().note=event.target.value;const ok=save();const label=$('.note-status');if(label)label.textContent=ok?'Saved on this device.':'Not saved. Export a backup before leaving.';}});
document.addEventListener('change',async event=>{
 if(event.target.id==='date-picker'&&event.target.value){selected=event.target.value;render()}
 if(event.target.name==='date'&&event.target.closest('#measure-form')){const d=day(event.target.value),f=event.target.form;f.elements.weight.value=d.weight??'';f.elements.waist.value=d.waist??'';}
 if(event.target.id==='import-file'){const file=event.target.files[0];event.target.value='';if(!file)return;if(file.size>5000000){toast('This backup is too large. Choose a Stride JSON backup.');return}try{const imported=normalize(JSON.parse(await file.text()));if(!confirm(`Restore ${Object.keys(imported.days).length} days from this backup? This replaces the logs and settings on this device.`))return;state=imported;state.settings.browserReminders=false;corrupt=false;saved('Backup restored. Browser alerts remain off until enabled.')}catch{toast('Could not read that backup. Choose a valid Stride JSON file.')}}
});
$('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)$('#modal').close()}});
window.addEventListener('hashchange',()=>{const hash=location.hash.slice(1);if(['today','plan','workout','progress','settings'].includes(hash)&&hash!==view){view=hash;render();window.scrollTo(0,0)}});
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;if(view==='settings')render()});
window.addEventListener('storage',event=>{if(event.key===KEY){try{if(event.newValue){state=normalize(JSON.parse(event.newValue));corrupt=false;render();toast('Updated from your other tab.')}}catch{toast('Another tab changed the data. Reload before editing.')}}});
let lastDay=localDate();const notified=new Set();
async function checkReminders(){const now=new Date(),date=localDate(now);if(date!==lastDay){if(selected===lastDay)selected=date;lastDay=date;render()}if(!state.settings.browserReminders||date<START||date>END)return;const time=`${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`,s=session(date),list=[];if(waterTimes(state.settings).includes(time)&&day(date).water<targets(state,date).water)list.push(['water','Time for a comfortable drink. Log a little hydration.']);if(state.settings.activityReminders&&!day(date).workout&&['run','strength','mobility'].includes(s.type)&&time===(s.type==='strength'?state.settings.strengthTime:state.settings.runTime))list.push(['activity',`${s.title}. ${s.detail}`]);for(const [kind,message] of list){const id=`${date}-${time}-${kind}`;let existing=false;try{existing=localStorage.getItem('stride-last-'+kind)===id}catch{}if(notified.has(id)||existing)continue;notified.add(id);try{localStorage.setItem('stride-last-'+kind,id)}catch{}await notify(message);toast(message)}}
setInterval(checkReminders,20000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkReminders()});
render();

// Native sessions are reconciled by stable ID. Never add step counters to Samsung totals.
function refreshNative(){if(!nativeApp||corrupt)return;try{const old=state.liveSessions||[];state.liveSessions=mergeLive(old,JSON.parse(window.AndroidStride.liveHistory()));window.AndroidStride.mergeLiveHistory(JSON.stringify(state.liveSessions));window.AndroidStride.updateWaterLog(localDate(),state.days[localDate()]?.water||0);if(JSON.stringify(old)!==JSON.stringify(state.liveSessions))save();render();}catch{toast('Live history could not be read. Your planner records are unchanged.')}}
window.addEventListener('stride-native-resume',refreshNative);
if(nativeApp)refreshNative();
setInterval(()=>{if(view==='workout'&&restUntil){const el=document.querySelector('#rest-countdown');if(el)el.textContent=Date.now()<restUntil?Math.ceil((restUntil-Date.now())/1000)+'s rest remaining':'Rest complete — ready when you are';}},1000);

window.addEventListener('stride-water-status',()=>{if(view==='settings')render()});
